[package]
name = "blit-core"
version.workspace = true
edition = "2021"
license.workspace = true
description = "High-performance file enumeration, planning, and transfer engine — the platform library behind the blit CLI and daemon, embeddable by any Rust front-end"
repository = "https://github.com/roethlar/Blit"
readme = "../../README.md"
keywords = ["file-transfer", "sync", "backup", "mirror", "rsync"]
categories = ["filesystem", "network-programming"]

[dependencies]
eyre = "0.6"
log = "0.4"
walkdir = "2.5"
globset = "0.4.18"
filetime = "0.2"
once_cell = "1.21"
rayon = "1.12"
chrono = { version = "0.4", default-features = false, features = ["clock"] }
sysinfo = { version = "0.38", default-features = false, features = ["disk", "system"] }
parking_lot = "0.12"
crossbeam-channel = "0.5"
async-trait = "0.1"
tar = "0.4"
# JOB_LOGS jl-1a: finished job logs are stored gzip-compressed
# (`<key>.jsonl.gz`), through the default pure-Rust (miniz_oxide) backend.
flate2 = "1"
# JOB_LOGS jl-2: the per-user `config.toml` (same crate/version the daemon
# reads its config with).
toml = "1.1"
num_cpus = "1.17"
serde = { version = "1.0", features = ["derive"] }
serde_json = "1.0"
directories = "6.0"
base64 = "0.22"
mdns-sd = "0.19"
hostname = "0.4"
build
deps
examples
incremental
